# PiliPlus media_kit_video render-timing test build
# Run on Windows with GitHub CLI (gh) and Git installed:
#   powershell -ExecutionPolicy Bypass -File setup-github.ps1
$ErrorActionPreference = "Stop"

gh auth status
$user = (gh api user -q .login).Trim()
if ([string]::IsNullOrWhiteSpace($user)) { throw "gh is not authenticated" }

$root = Join-Path (Get-Location) "PiliPlus-render-test"
if (-not (Test-Path $root)) {
  gh repo fork bggRGjQaUbCoE/PiliPlus --clone=true
  if (-not (Test-Path "PiliPlus")) { throw "fork/clone failed" }
  Rename-Item "PiliPlus" "PiliPlus-render-test"
}
Set-Location $root

# Enable Actions on the fork (ignore if the token lacks admin scope)
try {
  gh api -X PUT "repos/$user/PiliPlus/actions/permissions" -f enabled=true -f allowed_actions=all | Out-Null
} catch {
  Write-Host "Could not enable Actions automatically; enable them in the fork's Actions tab."
}

if (-not (git config user.email)) { git config user.email "$user@users.noreply.github.com" }
if (-not (git config user.name)) { git config user.name $user }

New-Item -ItemType Directory -Force "patches" | Out-Null
$mk = ""
$wf = ""
[IO.File]::WriteAllBytes((Join-Path $PWD "patches\media_kit_video_windows_render.patch"), [Convert]::FromBase64String($mk))
[IO.File]::WriteAllBytes((Join-Path $PWD "patches\win_x64_github_actions.patch"), [Convert]::FromBase64String($wf))

git checkout -B test/media-kit-render
git apply "patches/win_x64_github_actions.patch"
git add patches .github/workflows/win_x64.yml
git commit -m "test: media kit windows render timing"
git push -u origin test/media-kit-render

gh workflow run win_x64.yml --repo "$user/PiliPlus" --ref test/media-kit-render
Start-Sleep -Seconds 5
gh run list --repo "$user/PiliPlus" --workflow win_x64.yml --limit 3
Write-Host ""
Write-Host "When the run finishes:"
Write-Host "  gh run download <run-id> --repo $user/PiliPlus -n Windows-file-x64-release -D artifact"
Write-Host "Use the portable zip, not the installer."
